"""Shared interpolation of four certified scalar-coordinate boundary curves."""
import bpy
from .path_surface_nodes import _Nodes

NAME='Prochitecture Streets / Bundle boundary interpolation v1'


def build():
    tree=bpy.data.node_groups.get(NAME)
    if tree:return tree
    tree=bpy.data.node_groups.new(NAME,'GeometryNodeTree')
    for i in range(4):
        tree.interface.new_socket(name='Boundary '+str(i),in_out='INPUT',socket_type='NodeSocketGeometry')
        tree.interface.new_socket(name='Point '+str(i),in_out='OUTPUT',socket_type='NodeSocketVector')
    tree.interface.new_socket(name='Metric',in_out='INPUT',socket_type='NodeSocketFloat')
    g=_Nodes(tree);inp=g.node('NodeGroupInput','Certified boundary curves and physical coordinate')
    out=g.node('NodeGroupOutput','Actual boundary hits')
    for i in range(4):
        sample=g.node('GeometryNodeSampleCurve','Boundary '+str(i)+' interpolation')
        sample.mode='LENGTH';sample.data_type='FLOAT_VECTOR'
        g.set(inp.outputs['Boundary '+str(i)],sample.inputs['Curves'])
        g.set(inp.outputs['Metric'],sample.inputs['Length'])
        g.set(g.named('st_axis_xy','FLOAT_VECTOR'),sample.inputs['Value'])
        g.set(sample.outputs['Value'],out.inputs['Point '+str(i)])
    return tree


def evaluate(g,curves,metric):
    node=g.node('GeometryNodeGroup','Shared certified Bundle boundary interpolation')
    node.node_tree=build()
    for i,curve in enumerate(curves):g.set(curve,node.inputs['Boundary '+str(i)])
    g.set(metric,node.inputs['Metric'])
    return [node.outputs['Point '+str(i)] for i in range(4)]
